struct ui_state { int count; bool loading; const char *error; };
enum intent_kind { INTENT_INC, INTENT_REFRESH, INTENT_FAILED };
struct intent { enum intent_kind kind; const char *text; };

static struct ui_state reduce(struct ui_state s, const struct intent *in)
{
    switch (in->kind) {
    case INTENT_INC:     s.count += 1; break;
    case INTENT_REFRESH: s.loading = true; s.error = NULL; break;
    case INTENT_FAILED:  s.loading = false; s.error = in->text; break;
    }
    return s;                          /* copy - never mutate in place */
}
